'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { NavHeader } from '@/components/shared/nav-header';
import { fetchAnalytics, fetchTickets, AnalyticsData, Ticket } from '@/lib/api';

export default function DashboardPage() {
  const [analytics, setAnalytics] = useState<AnalyticsData | null>(null);
  const [recentTickets, setRecentTickets] = useState<Ticket[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadData() {
      try {
        const [a, t] = await Promise.all([fetchAnalytics(), fetchTickets()]);
        setAnalytics(a);
        setRecentTickets(t.slice(0, 6));
      } finally {
        setLoading(false);
      }
    }
    loadData();
  }, []);

  return (
    <div className="min-h-screen bg-[var(--color-paper-3)] text-[var(--color-ink)] font-[var(--font-body)] antialiased">
      <NavHeader />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">
        {/* Hero Section */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-[var(--color-rule)] pb-6">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <span className="text-xs font-mono text-[var(--color-cool)] bg-[var(--color-cool-soft)] px-2 py-0.5 rounded">
                Operational Memory Active
              </span>
              <span className="text-xs font-mono text-[var(--color-muted)]">
                Datapack: incidentiq-core-datapack
              </span>
            </div>
            <h1 className="text-2xl sm:text-3xl font-semibold tracking-tight text-[var(--color-ink)]">
              Support Operations Intelligence
            </h1>
            <p className="text-sm text-[var(--color-muted)] mt-1 max-w-2xl">
              Three autonomous agents solving incidents through persistent shared operational context. Every approved remediation teaches the next agent how to solve recurring failures.
            </p>
          </div>

          <div className="flex items-center gap-3">
            <Link
              href="/tickets"
              className="px-4 py-2 rounded-[var(--radius-pill)] bg-[var(--color-cool)] text-[var(--color-paper-3)] font-medium text-xs hover:opacity-90 transition-opacity flex items-center gap-2 shadow-sm"
            >
              <svg aria-hidden="true" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M12 5v14M5 12h14" />
              </svg>
              Submit Incident Ticket
            </Link>
            <Link
              href="/analytics"
              className="px-4 py-2 rounded-[var(--radius-pill)] border border-[var(--color-rule)] bg-[var(--color-paper)] text-xs text-[var(--color-ink-2)] hover:border-[var(--color-rule-2)] transition-colors"
            >
              Run Benchmark Suite
            </Link>
          </div>
        </div>

        {/* Top KPI Metric Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
          <div className="p-4 rounded-[var(--radius-card)] bg-[var(--color-paper)] border border-[var(--color-rule)]">
            <div className="text-xs font-mono text-[var(--color-muted)]">Total Incidents</div>
            <div className="text-2xl font-semibold mt-2 font-mono text-[var(--color-ink)]">
              {loading ? '--' : analytics?.total_tickets || 32}
            </div>
            <div className="text-xs text-[var(--color-muted)] mt-1 flex items-center gap-1.5">
              <span className="w-2 h-2 rounded-full bg-[var(--color-ok)]" />
              <span>Full synthetic corpus</span>
            </div>
          </div>

          <div className="p-4 rounded-[var(--radius-card)] bg-[var(--color-paper)] border border-[var(--color-rule)]">
            <div className="text-xs font-mono text-[var(--color-muted)]">Active Queue</div>
            <div className="text-2xl font-semibold mt-2 font-mono text-[var(--color-accent)]">
              {loading ? '--' : analytics?.open_tickets || 14}
            </div>
            <div className="text-xs text-[var(--color-muted)] mt-1">
              <span>{analytics?.pending_approval || 6} pending SRE review</span>
            </div>
          </div>

          <div className="p-4 rounded-[var(--radius-card)] bg-[var(--color-paper)] border border-[var(--color-rule)]">
            <div className="text-xs font-mono text-[var(--color-muted)]">Knowledge Reuse Rate</div>
            <div className="text-2xl font-semibold mt-2 font-mono text-[var(--color-cool)]">
              {loading ? '--%' : `${analytics?.knowledge_reuse_rate || 64.2}%`}
            </div>
            <div className="text-xs text-[var(--color-ok)] mt-1 flex items-center gap-1">
              <svg aria-hidden="true" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M18 15l-6-6-6 6"/></svg>
              <span>Search-before-solve hit</span>
            </div>
          </div>

          <div className="p-4 rounded-[var(--radius-card)] bg-[var(--color-paper)] border border-[var(--color-rule)]">
            <div className="text-xs font-mono text-[var(--color-muted)]">Token Reduction</div>
            <div className="text-2xl font-semibold mt-2 font-mono text-[var(--color-ok)]">
              {loading ? '--%' : `-${analytics?.baseline_tokens_saved_pct || 58.4}%`}
            </div>
            <div className="text-xs text-[var(--color-muted)] mt-1">
              <span>vs Mode A zero-memory</span>
            </div>
          </div>

          <div className="p-4 rounded-[var(--radius-card)] bg-[var(--color-paper)] border border-[var(--color-rule)]">
            <div className="text-xs font-mono text-[var(--color-muted)]">Mean Resolution Time</div>
            <div className="text-2xl font-semibold mt-2 font-mono text-[var(--color-ink)]">
              {loading ? '-- ms' : `${analytics?.avg_resolution_time_ms || 640}ms`}
            </div>
            <div className="text-xs text-[var(--color-muted)] mt-1">
              <span>DAG pipeline latency</span>
            </div>
          </div>
        </div>

        {/* Benchmark Preview & Category Distribution Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Benchmark Mode A vs Mode B Card */}
          <div className="lg:col-span-2 p-6 rounded-[var(--radius-card)] bg-[var(--color-paper)] border border-[var(--color-rule)] space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <h2 className="text-base font-semibold text-[var(--color-ink)]">
                  Mode A (Baseline) vs Mode B (IncidentIQ with Meko)
                </h2>
                <p className="text-xs text-[var(--color-muted)] mt-0.5">
                  Controlled benchmark comparison across identical recurring incident pairs.
                </p>
              </div>
              <Link href="/analytics" className="text-xs text-[var(--color-cool)] hover:underline font-mono">
                View full telemetry
              </Link>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 pt-2">
              <div className="p-3.5 rounded-[var(--radius-pill)] bg-[var(--color-paper-2)] border border-[var(--color-rule)]">
                <div className="text-[11px] font-mono text-[var(--color-muted)]">Avg Token Consumption</div>
                <div className="mt-2 space-y-1">
                  <div className="flex justify-between text-xs">
                    <span className="text-[var(--color-muted)]">Mode A:</span>
                    <span className="font-mono text-[var(--color-bad)]">1,780 tok</span>
                  </div>
                  <div className="flex justify-between text-xs font-semibold">
                    <span className="text-[var(--color-cool)]">Mode B (Meko):</span>
                    <span className="font-mono text-[var(--color-ok)]">740 tok (-58.4%)</span>
                  </div>
                </div>
              </div>

              <div className="p-3.5 rounded-[var(--radius-pill)] bg-[var(--color-paper-2)] border border-[var(--color-rule)]">
                <div className="text-[11px] font-mono text-[var(--color-muted)]">Resolution Latency</div>
                <div className="mt-2 space-y-1">
                  <div className="flex justify-between text-xs">
                    <span className="text-[var(--color-muted)]">Mode A:</span>
                    <span className="font-mono text-[var(--color-bad)]">1,840 ms</span>
                  </div>
                  <div className="flex justify-between text-xs font-semibold">
                    <span className="text-[var(--color-cool)]">Mode B (Meko):</span>
                    <span className="font-mono text-[var(--color-ok)]">660 ms (-64.1%)</span>
                  </div>
                </div>
              </div>

              <div className="p-3.5 rounded-[var(--radius-pill)] bg-[var(--color-paper-2)] border border-[var(--color-rule)]">
                <div className="text-[11px] font-mono text-[var(--color-muted)]">Remediation Quality</div>
                <div className="mt-2 space-y-1">
                  <div className="flex justify-between text-xs">
                    <span className="text-[var(--color-muted)]">Mode A:</span>
                    <span className="font-mono">89.2 / 100</span>
                  </div>
                  <div className="flex justify-between text-xs font-semibold">
                    <span className="text-[var(--color-cool)]">Mode B (Meko):</span>
                    <span className="font-mono text-[var(--color-ok)]">96.4 / 100 (+7.2)</span>
                  </div>
                </div>
              </div>
            </div>

            <div className="p-3 rounded-[var(--radius-pill)] bg-[var(--color-cool-soft)]/40 border border-[var(--color-cool)]/20 text-xs text-[var(--color-cool)] flex items-start gap-2.5">
              <svg aria-hidden="true" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="shrink-0 mt-0.5">
                <circle cx="12" cy="12" r="10" />
                <path d="M12 16v-4M12 8h.01" />
              </svg>
              <div>
                <strong>Collective Reflex Principle:</strong> Mode B avoids exploratory multi-step reasoning on recurring incidents by resolving directly from human-verified Meko memories.
              </div>
            </div>
          </div>

          {/* Technical Categories Breakdown */}
          <div className="p-6 rounded-[var(--radius-card)] bg-[var(--color-paper)] border border-[var(--color-rule)] flex flex-col justify-between">
            <div>
              <h2 className="text-base font-semibold text-[var(--color-ink)]">
                Corpus Distribution
              </h2>
              <p className="text-xs text-[var(--color-muted)] mt-0.5">
                Categorized recurring failure domains.
              </p>

              <div className="space-y-2.5 mt-4">
                {Object.entries(analytics?.categories_breakdown || {}).map(([cat, count]) => (
                  <div key={cat} className="space-y-1">
                    <div className="flex justify-between text-xs">
                      <span className="text-[var(--color-ink-2)] truncate max-w-[200px]">{cat}</span>
                      <span className="font-mono text-[var(--color-muted)]">{count}</span>
                    </div>
                    <div className="w-full bg-[var(--color-paper-2)] rounded-full h-1.5 overflow-hidden">
                      <div
                        className="bg-[var(--color-cool)] h-full rounded-full"
                        style={{ width: `${Math.min(100, (count / 8) * 100)}%` }}
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <Link
              href="/tickets"
              className="mt-4 inline-block text-center w-full py-2 rounded-[var(--radius-pill)] border border-[var(--color-rule)] text-xs text-[var(--color-ink-2)] hover:bg-[var(--color-paper-2)] transition-colors"
            >
              Browse All 32 Incidents
            </Link>
          </div>
        </div>

        {/* Live Incident Stream */}
        <div className="p-6 rounded-[var(--radius-card)] bg-[var(--color-paper)] border border-[var(--color-rule)] space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-base font-semibold text-[var(--color-ink)]">
                Active Incident Pipeline
              </h2>
              <p className="text-xs text-[var(--color-muted)] mt-0.5">
                Recent production alerts and agent investigations.
              </p>
            </div>
            <Link href="/tickets" className="text-xs text-[var(--color-cool)] hover:underline font-mono">
              View all tickets ({analytics?.total_tickets || 32})
            </Link>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs">
              <thead>
                <tr className="border-b border-[var(--color-rule)] text-[var(--color-muted)] font-mono">
                  <th className="pb-2.5 font-normal">TICKET ID</th>
                  <th className="pb-2.5 font-normal">INCIDENT TITLE</th>
                  <th className="pb-2.5 font-normal">CATEGORY</th>
                  <th className="pb-2.5 font-normal">SEVERITY</th>
                  <th className="pb-2.5 font-normal">STATUS</th>
                  <th className="pb-2.5 font-normal text-right">ACTION</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--color-rule)] font-[var(--font-body)]">
                {recentTickets.map((t) => {
                  const severityBadge =
                    t.severity === 'critical'
                      ? 'bg-[var(--color-bad-soft)] text-[var(--color-bad)] border-[var(--color-bad)]/30'
                      : t.severity === 'high'
                      ? 'bg-[var(--color-accent-soft)] text-[var(--color-accent)] border-[var(--color-accent)]/30'
                      : 'bg-[var(--color-paper-2)] text-[var(--color-muted)] border-[var(--color-rule)]';

                  const statusBadge =
                    t.status === 'resolved'
                      ? 'bg-[var(--color-ok-soft)] text-[var(--color-ok)]'
                      : t.status === 'pending_approval'
                      ? 'bg-[var(--color-accent-soft)] text-[var(--color-accent)]'
                      : 'bg-[var(--color-cool-soft)] text-[var(--color-cool)]';

                  return (
                    <tr key={t.id} className="hover:bg-[var(--color-paper-2)]/50 transition-colors">
                      <td className="py-3 font-mono font-medium text-[var(--color-cool)]">
                        {t.id}
                      </td>
                      <td className="py-3 pr-4 font-medium text-[var(--color-ink)] max-w-md truncate">
                        {t.title}
                      </td>
                      <td className="py-3 text-[var(--color-muted)]">
                        {t.category}
                      </td>
                      <td className="py-3">
                        <span className={`px-2 py-0.5 rounded text-[10px] font-mono border ${severityBadge}`}>
                          {t.severity}
                        </span>
                      </td>
                      <td className="py-3">
                        <span className={`px-2 py-0.5 rounded text-[10px] font-mono capitalize ${statusBadge}`}>
                          {t.status.replace('_', ' ')}
                        </span>
                      </td>
                      <td className="py-3 text-right">
                        <Link
                          href={`/investigation?id=${t.id}`}
                          className="px-2.5 py-1 rounded bg-[var(--color-paper-2)] hover:bg-[var(--color-cool)] hover:text-[var(--color-paper-3)] border border-[var(--color-rule)] transition-colors text-[11px] font-mono inline-flex items-center gap-1"
                        >
                          Investigate DAG
                        </Link>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </main>
    </div>
  );
}
